rp87 "$WORK/rv87-g2.md" 1 0 -
cy87 S3 2 1 0 "$WORK/rv87-g2.md"
check "87b: S3 의 둘째 P0 사이클이 기록된다 (아래가 공허하지 않다)" "$rc" "0"
snap87=$( cd "$WT" && XDG_STATE_HOME="$STATE_LATE" gate_inproc snapshot --manifest "$WORK/plan-R87.md" 2>/dev/null )
